 function paymentRows(receipts,allocations,docs){return receipts.map(row=>{const linked=allocations.filter(item=>item.payment_receipt_id===row.id),docLabels=linked.map(item=>{const doc=docs.find(value=>value.id===item.document_id);return`<button class="ops-link" onclick="event.stopPropagation();PilozApp.go('document-viewer?id=${item.document_id}')">${esc(doc?.number||'Facture')}</button>`;}).join(' ');return`<tr data-search="${attr(`${row.payment_number} ${currentClientName(row.client_id)} ${row.external_reference||''}`.toLowerCase())}" data-method="${attr(row.payment_method||'')}" data-date="${attr(String(row.received_at||'').slice(0,10))}" onclick="PilozOps.openPayment('${row.id}')"><td class="primary">${esc(row.payment_number)}</td><td>${date(row.received_at)}</td><td>${esc(currentClientName(row.client_id))}</td><td>${docLabels||'—'}</td><td class="money">${money(row.received_amount,row.currency)}</td><td class="money">${money(row.allocated_amount,row.currency)}</td><td class="money">${money(row.unallocated_amount,row.currency)}</td><td>${esc(row.payment_method)}</td><td>${esc(row.external_reference||'—')}</td><td><button class="ops-icon-button" title="Détail" onclick="event.stopPropagation();PilozOps.openPayment('${row.id}')">›</button></td></tr>`;}).join('')||`<tr><td colspan="10">${empty('Aucun règlement','Les règlements confirmés apparaîtront ici.')}</td></tr>`;}
