 function openPayment(id){const row=ui.receipts.find(value=>value.id===id),allocations=ui.allocations.filter(value=>value.payment_receipt_id===id),docs=state().data.documents||[];if(!row)return;modal(`Règlement ${row.payment_number}`,`<div class="ops-detail-grid"><dl><div><dt>Client</dt><dd>${esc(currentClientName(row.client_id))}</dd></div><div><dt>Date de réception</dt><dd>${datetime(row.received_at)}</dd></div><div><dt>Moyen</dt><dd>${esc(row.payment_method)}</dd></div><div><dt>Référence</dt><dd>${esc(row.external_reference||'—')}</dd></div><div><dt>Montant reçu</dt><dd>${money(row.received_amount,row.currency)}</dd></div><div><dt>Non affecté</dt><dd>${money(row.unallocated_amount,row.currency)}</dd></div></dl><section><h3>Affectations</h3>${allocations.map(item=>{const doc=docs.find(value=>value.id===item.document_id);return`<button class="ops-allocation" onclick="PilozApp.go('document-viewer?id=${item.document_id}')"><span><b>${esc(doc?.number||'Facture')}</b><small>${date(doc?.issue_date)}</small></span><strong>${money(item.amount,row.currency)}</strong></button>`;}).join('')||'<p>Aucune affectation.</p>'}</section></div><div class="ops-warning"><strong>Correction traçable</strong><p>L’annulation crée des écritures inverses ; elle ne supprime jamais le règlement initial.</p></div><div class="ops-modal-actions">${button('Fermer','PilozOps.closeModal()','btn-o')}${button('Annuler / corriger le règlement',`PilozOps.reversePayment('${row.id}')`,'btn-danger')}</div>`,true);}
