 async function accountingData(companyId,force=false){if(!force&&ui.accountingCache&&ui.accountingCacheCompany===companyId)return ui.accountingCache;const tables=['accounting_fiscal_years','accounting_journals','accounting_settings','accounting_account_mappings','accounting_vat_mappings','accounting_financial_accounts','accounting_payment_method_mappings','accounting_complementary_accounts'];const values=await Promise.all(tables.map(table=>api().query(table,`select=*&company_id=eq.${companyId}&order=created_at.asc`)));ui.accountingCache=Object.fromEntries(tables.map((table,index)=>[table,values[index]]));ui.accountingCacheCompany=companyId;return ui.accountingCache;}
