 const tabs=[['exercises','Exercices fiscaux'],['journals','Journaux'],['tiers','Tiers'],['deposits','Acomptes'],['sales','Ventes'],['purchases','Achats'],['vat','TVA'],['financial','Comptes financiers'],['complementary','Comptes complémentaires']];
 function inputRow(table,row,fields){return`<tr data-table="${table}" data-id="${row.id||''}">${fields.map(([key,label,type='text'])=>`<td data-label="${esc(label)}"><input data-field="${key}" type="${type}" value="${attr(type==='checkbox'?'':row[key]??'')}" ${type==='checkbox'&&row[key]?'checked':''}></td>`).join('')}</tr>`;}
 function tableBlock(headers,rows,emptyText='Aucune donnée'){return`<div class="modern-table-shell"><table class="modern-table ops-config-table"><thead><tr>${headers.map(value=>`<th>${esc(value)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}">${esc(emptyText)}</td></tr>`}</tbody></table></div>`;}
 function thirdPartyPanel(data,settings){
  const currentIdentifiers=new Map((data.accounting_third_party_identifiers||[]).filter(row=>!row.effective_until).map(row=>[`${row.party_type}:${row.party_id}`,row.identifier]));
  const clientProfiles=new Map((data.client_accounting_profiles||[]).filter(row=>row.active!==false).map(row=>[row.client_id,row]));
  const supplierProfiles=new Map((data.supplier_accounting_profiles||[]).filter(row=>row.active!==false).map(row=>[row.supplier_id,row]));
  const reserved=new Set(),legacy=value=>/^(CLI|FOU)\d+$/i.test(String(value||''));
  for(const value of [...clientProfiles.values(),...supplierProfiles.values()].map(row=>row.auxiliary_account).filter(value=>value&&!legacy(value)))reserved.add(String(value).toUpperCase());
  for(const value of currentIdentifiers.values())if(value&&!legacy(value))reserved.add(String(value).toUpperCase());
  const proposed=label=>{const base=normalizedThirdPartyIdentifier(label)||'TIERS';let value=base,index=1;while(reserved.has(value)){const suffix=String(index++);value=base.slice(0,Math.max(1,10-suffix.length))+suffix;}reserved.add(value);return value;};
  const partyRow=(kind,party,profile)=>{const label=thirdPartyName(party,kind==='client'?'Client':'Fournisseur'),stored=profile?.auxiliary_account||currentIdentifiers.get(`${kind}:${party.id}`)||'',value=!stored||legacy(stored)?proposed(label):String(stored).toUpperCase(),type=kind==='client'?(party.kind==='person'?'Particulier':'Professionnel'):'Fournisseur';return`<tr><td data-label="Tiers"><b>${esc(label)}</b></td><td data-label="Type">${esc(type)}</td><td data-label="Identifiant"><input class="ops-third-party-identifier" data-third-party-kind="${kind}" data-third-party-id="${party.id}" data-original="${attr(stored)}" value="${attr(value)}" maxlength="10" pattern="[A-Z0-9]{1,10}" autocomplete="off" aria-label="Identifiant ${kind==='client'?'client':'fournisseur'} de ${attr(label)}"></td></tr>`;};
  const clients=(data.clients||[]).filter(item=>item.active!==false).map(item=>partyRow('client',item,clientProfiles.get(item.id))).join('');
  const suppliers=(data.suppliers||[]).filter(item=>item.active!==false).map(item=>partyRow('supplier',item,supplierProfiles.get(item.id))).join('');
  return`${settingsPanel(settings,[['customer_collective_account','Compte collectif clients'],['supplier_collective_account','Compte collectif fournisseurs'],['customer_auxiliary_enabled','Utiliser un identifiant auxiliaire pour les clients','checkbox'],['supplier_auxiliary_enabled','Utiliser un identifiant auxiliaire pour les fournisseurs','checkbox']],'Tiers et comptes auxiliaires','Chaque tiers possède son propre identifiant : raison sociale pour un professionnel ou nom du particulier. Les anciens préfixes génériques CLI et FOU ne sont plus proposés.')}<div class="ops-info-callout"><strong>Identifiants individuels</strong><span>Ils sont normalisés sur 10 caractères et restent uniques dans l’entreprise. Vous pouvez les adapter avant d’enregistrer.</span></div><h3>Clients</h3>${tableBlock(['Client','Type','Identifiant client'],clients,'Aucun client actif')}<h3>Fournisseurs</h3>${tableBlock(['Fournisseur','Type','Identifiant fournisseur'],suppliers,'Aucun fournisseur actif')}`;
 }
 function accountingPanel(data,tab){const settings=data.accounting_settings[0]||{};if(tab==='exercises')return`<div class="ops-section-head"><div><h2>Exercices fiscaux</h2><p>Les périodes ne peuvent pas se chevaucher. La clôture contrôle les écritures avant de verrouiller l’exercice.</p></div>${button('Nouvel exercice',"PilozOps.addAccounting('fiscal')",'btn-o')}</div>${tableBlock(['Nom','Début','Fin','Statut','Actions'],data.accounting_fiscal_years.map(row=>`${inputRow('accounting_fiscal_years',row,[['name','Nom'],['starts_on','Début','date'],['ends_on','Fin','date'],['status','Statut']]).replace('</tr>',`<td data-label="Actions"><div class="actions">${row.next_year_id?'':button('Créer N+1',`PilozOps.createNextFiscal('${row.id}')`,'btn-o')}${row.status==='closed'?status('Clôturé','success'):button('Clôturer',`PilozOps.closeFiscal('${row.id}')`,'btn-o')}</div></td></tr>`)}`).join(''))}`;
 if(tab==='journals')return`<div class="ops-section-head"><div><h2>Journaux</h2><p>Ventes, achats, banque, caisse et opérations diverses.</p></div>${button('Nouveau journal',"PilozOps.addAccounting('journal')",'btn-o')}</div>${tableBlock(['Code','Libellé','Type','Ordre','Actif'],data.accounting_journals.map(row=>inputRow('accounting_journals',row,[['code','Code'],['label','Libellé'],['journal_type','Type'],['display_order','Ordre','number'],['active','Actif','checkbox']])).join(''))}`;
 if(tab==='tiers')return thirdPartyPanel(data,settings);
 if(tab==='deposits')return settingsPanel(settings,[['deposit_account','Compte d’acompte'],['deposit_method','Méthode'],['deposit_apply_auxiliary','Appliquer l’auxiliaire','checkbox']],'Comptabilisation des acomptes','Le compte dédié est utilisé pour la déduction d’acompte et préserve l’équilibre de la facture finale.');
 if(tab==='sales'||tab==='purchases'){const direction=tab==='sales'?'sale':'purchase',rows=data.accounting_account_mappings.filter(row=>row.direction===direction);return`<div class="ops-section-head"><div><h2>${tab==='sales'?'Comptes de vente':'Comptes d’achat'}</h2><p>Priorité : article, catégorie, type, puis compte global.</p></div>${button('Ajouter une règle',`PilozOps.addAccounting('${direction}')`,'btn-o')}</div>${tableBlock(['Portée','Valeur','Compte','Extension TVA','Actif'],rows.map(row=>inputRow('accounting_account_mappings',row,[['scope_type','Portée'],['scope_value','Valeur'],['account_code','Compte'],['vat_extension','Extension TVA'],['active','Actif','checkbox']])).join(''))}`;}
 if(tab==='vat')return`<div class="ops-section-head"><div><h2>Comptes de TVA</h2><p>Les taux actifs utilisés sans compte configuré sont signalés par le contrôle.</p></div>${button('Ajouter un taux',"PilozOps.addAccounting('vat')",'btn-o')}</div>${tableBlock(['Taux','TVA achats','TVA ventes','Compte d’attente','Extension vente','Extension achat'],data.accounting_vat_mappings.map(row=>inputRow('accounting_vat_mappings',row,[['tax_rate','Taux','number'],['purchase_account','TVA achats'],['sales_account','TVA ventes'],['suspense_account','Attente'],['sale_account_extension','Ext. vente'],['purchase_account_extension','Ext. achat']])).join(''))}`;
 if(tab==='financial')return`<div class="ops-section-head"><div><h2>Comptes financiers</h2><p>Banques, caisse et comptes d’attente des moyens de paiement.</p></div>${button('Ajouter un compte',"PilozOps.addAccounting('financial')",'btn-o')}</div>${tableBlock(['Nom','Type','IBAN (4 derniers)','Compte','Journal (id)','Actif'],data.accounting_financial_accounts.map(row=>inputRow('accounting_financial_accounts',row,[['name','Nom'],['account_type','Type'],['iban_last4','IBAN'],['account_code','Compte'],['journal_id','Journal'],['active','Actif','checkbox']])).join(''))}<h3>Moyens de paiement</h3>${tableBlock(['Moyen','Compte financier','Extension','Journal (id)','Attente','Actif'],data.accounting_payment_method_mappings.map(row=>inputRow('accounting_payment_method_mappings',row,[['payment_method','Moyen'],['financial_account_code','Compte'],['account_extension','Extension'],['journal_id','Journal'],['suspense_account','Attente'],['active','Actif','checkbox']])).join(''))}`;
 return`<div class="ops-section-head"><div><h2>Comptes complémentaires</h2><p>Escomptes, retenues, prorata, révisions et autres déductions.</p></div>${button('Ajouter un compte',"PilozOps.addAccounting('complementary')",'btn-o')}</div>${tableBlock(['Libellé','Clé','Compte','Auxiliaire','TVA','Actif'],data.accounting_complementary_accounts.map(row=>inputRow('accounting_complementary_accounts',row,[['label','Libellé'],['setting_key','Clé'],['account_code','Compte'],['apply_auxiliary','Auxiliaire','checkbox'],['vat_rate','TVA','number'],['active','Actif','checkbox']])).join(''))}`;}
 function settingsPanel(settings,fields,title,description){return`<h2>${esc(title)}</h2><p>${esc(description)}</p><div class="ops-settings-fields" data-settings="true">${fields.map(([key,label,type='text'])=>type==='checkbox'?`<label class="ops-check"><input data-field="${key}" type="checkbox" ${settings[key]?'checked':''}><span>${esc(label)}</span></label>`:field(label,key,settings[key]??'',type).replace('<input','<input data-field="'+key+'"')).join('')}</div>`;}
 async function renderAccountingSettings(s,force=false){const currentPath=path(),requestedTab=currentPath.startsWith('accounting/settings/')?currentPath.split('/').pop():'exercises';if(tabs.some(([key])=>key===requestedTab))ui.accountingTab=requestedTab;loading('Paramétrage comptable','Exercices, journaux, comptes, TVA et règles de ventilation.');try{const data=await accountingData(s.companyId,force);if(ui.accountingTab==='tiers')Object.assign(data,await thirdPartyData(s.companyId));if(!path().startsWith('accounting/settings'))return;document.getElementById('main').innerHTML=header('Paramétrage comptable','Les nouvelles valeurs s’appliquent aux écritures futures. Les exports déjà figés ne sont jamais modifiés.',`${button('Contrôler le paramétrage','PilozOps.controlAccounting()','btn-o')}${button('Enregistrer','PilozOps.saveAccounting()','btn-p')}`)+`<nav class="ops-tabs">${tabs.map(([key,label])=>`<button class="${ui.accountingTab===key?'active':''}" onclick="PilozOps.setAccountingTab('${key}')">${esc(label)}</button>`).join('')}</nav><section class="phase1-card ops-accounting-form">${accountingPanel(data,ui.accountingTab)}</section><div class="ops-sticky-save">${button('Enregistrer les modifications','PilozOps.saveAccounting()','btn-p')}</div>`;}catch(error){fail(error);}}
 function setAccountingTab(tab){if(!tabs.some(([key])=>key===tab))return;ui.accountingTab=tab;app().go(`accounting/settings/${tab}`);}
 async function createNextFiscal(id){try{await api().rpc('create_next_accounting_fiscal_year',{target_fiscal_year_id:id});ui.accountingCache=null;notify('Exercice suivant créé sans chevauchement.','success');renderAccountingSettings(state(),true);}catch(error){fail(error);}}
 async function closeFiscal(id){if(!global.confirm('Clôturer cet exercice après contrôle de toutes les écritures ?'))return;try{await api().rpc('close_accounting_fiscal_year',{target_fiscal_year_id:id});ui.accountingCache=null;notify('Exercice contrôlé et clôturé.','success');renderAccountingSettings(state(),true);}catch(error){fail(error);}}
 async function saveAccounting(){try{const s=state(),settingsNode=document.querySelector('[data-settings="true"]');if(settingsNode){const payload={company_id:s.companyId};settingsNode.querySelectorAll('[data-field]').forEach(input=>payload[input.dataset.field]=input.type==='checkbox'?input.checked:input.type==='number'?(input.value===''?null:Number(input.value)):input.value);await api().request('/rest/v1/accounting_settings?on_conflict=company_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(payload)});}for(const row of document.querySelectorAll('.ops-config-table tr[data-id]')){const payload={};row.querySelectorAll('[data-field]').forEach(input=>payload[input.dataset.field]=input.type==='checkbox'?input.checked:input.type==='number'?(input.value===''?null:Number(input.value)):input.value||null);await api().update(row.dataset.table,row.dataset.id,payload);}for(const input of document.querySelectorAll('.ops-third-party-identifier')){const identifier=normalizedThirdPartyIdentifier(input.value);if(!identifier)throw new Error('Chaque tiers doit posséder un identifiant.');if(identifier===String(input.dataset.original||'').toUpperCase())continue;if(input.dataset.thirdPartyKind==='client'){await api().rpc('assign_client_auxiliary_account',{target_client_id:input.dataset.thirdPartyId,target_assignment_mode:'manual',target_auxiliary_account:identifier,target_collective_account:null,target_effective_from:null,target_reason:'Identifiant modifié depuis le paramétrage comptable',target_confirm_existing_documents:true});}else{await api().request('/rest/v1/supplier_accounting_profiles?on_conflict=company_id,supplier_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({company_id:s.companyId,supplier_id:input.dataset.thirdPartyId,auxiliary_account:identifier,assignment_mode:'manual',accounting_label:thirdPartyName((s.data.suppliers||[]).find(row=>row.id===input.dataset.thirdPartyId),'Fournisseur'),active:true})});}}ui.accountingCache=null;notify('Paramétrage comptable et identifiants des tiers enregistrés.','success');renderAccountingSettings(s,true);}catch(error){fail(error);}}
 async function addAccounting(kind){const s=state();try{if(kind==='fiscal'){const year=String(global.prompt('Année de l’exercice',String(new Date().getFullYear()))||'').trim();if(!/^\d{4}$/.test(year))return;await api().insert('accounting_fiscal_years',{company_id:s.companyId,name:year,starts_on:`${year}-01-01`,ends_on:`${year}-12-31`,status:'open'});}else if(kind==='journal'){const code=String(global.prompt('Code du journal','OD')||'').trim().toUpperCase(),label=String(global.prompt('Libellé','Opérations diverses')||'').trim();if(!code||!label)return;await api().insert('accounting_journals',{company_id:s.companyId,code,label,journal_type:'adjustment',active:true});}else if(['sale','purchase'].includes(kind)){const account=String(global.prompt('Numéro de compte',kind==='sale'?'706000':'607000')||'').trim();if(!account)return;await api().insert('accounting_account_mappings',{company_id:s.companyId,direction:kind,scope_type:'global',scope_value:'*',account_code:account,active:true});}else if(kind==='vat'){const rate=Number(global.prompt('Taux de TVA','20'));if(!Number.isFinite(rate))return;await api().insert('accounting_vat_mappings',{company_id:s.companyId,tax_rate:rate,active:true});}else if(kind==='financial'){const name=String(global.prompt('Nom du compte','Banque principale')||'').trim();if(!name)return;await api().insert('accounting_financial_accounts',{company_id:s.companyId,name,account_type:'bank',account_code:'512100',active:true});}else{const label=String(global.prompt('Libellé du compte','Autre déduction')||'').trim();if(!label)return;await api().insert('accounting_complementary_accounts',{company_id:s.companyId,setting_key:`custom_${Date.now()}`,label,account_code:'471000',active:true});}ui.accountingCache=null;renderAccountingSettings(s,true);}catch(error){fail(error);}}
 async function controlAccounting(){try{const report=unwrap(await api().rpc('validate_accounting_configuration',{target_company_id:state().companyId}));modal('Contrôle du paramétrage',`<div class="ops-preview-summary">${status(report.ok?'Paramétrage exploitable':'Erreurs bloquantes',report.ok?'success':'danger')}</div>${[['Bloquant',report.blocking,'danger'],['Avertissement',report.warnings,'warning'],['Information',report.information,'info']].map(([title,items,tone])=>`<section class="ops-report-section"><h3>${esc(title)}</h3>${(items||[]).map(item=>`<p class="${tone}">${esc(item.message)}</p>`).join('')||'<p>Aucun.</p>'}</section>`).join('')}<div class="ops-modal-actions">${button('Fermer','PilozOps.closeModal()','btn-p')}</div>`,true);}catch(error){fail(error);}}

 async function renderSettingsDashboard(s){loading('Paramètres','État de votre entreprise, de vos services et de vos obligations.');try{const connections=await api().query('external_connections',`select=id,status&company_id=eq.${s.companyId}`);if(!['settings','settings/overview'].includes(path()))return;const company=s.data.settings?.[0]||{},configured=Boolean(company.legal_name&&company.siret),cards=[['settings/company','⌂','Mon entreprise','Identité, coordonnées, adresses et informations légales.',configured?'Configuré':'À compléter',configured?'success':'warning'],['settings/sales','€','Ventes et documents','TVA, numérotation, conditions et documents commerciaux.','Configuré','success'],['settings/company/bank','▣','Banque et règlements','Coordonnées bancaires et moyens de paiement.',company.iban?'Configuré':'À compléter',company.iban?'success':'warning'],['settings/users','♙','Équipe et accès','Membres, rôles et droits.','Gérer','info'],['settings/extensions','◉','Extensions','Agendas et messageries connectés.',`${connections.filter(row=>row.status==='connected').length} service(s) connecté(s)`,connections.some(row=>row.status==='error')?'danger':'info'],['settings/data','↯','Notifications','Préférences, activités et données.','À compléter','warning'],['settings/security','◇','Sécurité','Méthodes de connexion et protection du compte.','Configuré','success'],['settings/subscription','◆','Abonnement et utilisation','Offre, limites et facturation Piloz.','Voir l’offre','info'],['settings/compliance','✓','Conformité','Contrôles fiscaux, RGPD et sécurité.','Contrôler','info'],['settings/about-compliance','i','À propos de Piloz','Version et périmètre fonctionnel.','Informations','muted'],['settings/templates','✎','Modèles de documents','Modèles, logos, couleurs, colonnes, pieds de page et CGV.','Configurer','info']];document.getElementById('main').innerHTML=header('Paramètres','Retrouvez tous les réglages de votre entreprise et leur état actuel.')+`<div class="ops-settings-dashboard">${cards.map(([route,icon,title,description,label,tone])=>`<button onclick="PilozApp.go('${route}')"><span class="icon">${esc(icon)}</span><span class="copy"><b>${esc(title)}</b><small>${esc(description)}</small></span>${status(label,tone)}<span class="chevron">›</span></button>`).join('')}</div>`;}catch(error){fail(error);baseRender('settings',s);}}

 async function currentAuthUser(){const runtime=global.PilozRuntime,session=runtime?.session;if(!runtime?.config?.url||!runtime?.config?.key||!session?.access_token)return null;const response=await fetch(runtime.config.url.replace(/\/$/,'')+'/auth/v1/user',{headers:{apikey:runtime.config.key,Authorization:'Bearer '+session.access_token}});return response.ok?response.json():null;}
 async function renderSecurity(s){loading('Sécurité','Méthodes de connexion et protection de votre compte.');try{const user=await currentAuthUser();if(path()!=='settings/security')return;const identities=user?.identities||[],providers=new Map(identities.map(identity=>[identity.provider,identity])),emailIdentity=providers.get('email'),google=providers.get('google'),microsoft=providers.get('azure'),methodCount=[emailIdentity,google,microsoft].filter(Boolean).length,connection=(label,provider,identity)=>`<article class="ops-login-method"><span class="ops-extension-logo ${provider}">${providerLogo(provider)}</span><div><b>${esc(label)}</b><small>${identity?`Connecté · ${esc(identity.identity_data?.email||user?.email||'')}`:'Non connecté'}</small></div>${identity?(methodCount>1?button('Délier',`PilozOps.unlinkIdentity('${identity.id}')`,'btn-o'):status('Méthode requise','warning')):button('Lier',`PilozOps.linkIdentity('${provider}')`,'btn-p')}</article>`;document.getElementById('main').innerHTML=header('Méthodes de connexion','Piloz empêche de supprimer la dernière méthode permettant d’accéder au compte.')+`<section class="phase1-card"><div class="ops-account-summary"><div><small>Adresse principale</small><strong>${esc(user?.email||global.PilozRuntime?.session?.email||'—')}</strong></div><div><small>Dernière connexion</small><strong>${datetime(user?.last_sign_in_at)}</strong></div></div><div class="ops-login-methods">${connection('Adresse e-mail','email',emailIdentity)}${connection('Google','google',google)}${connection('Microsoft','azure',microsoft)}</div></section><aside class="ops-info-callout"><strong>Protection du compte</strong><span>Le rattachement et le retrait d’une identité sont traités directement par Supabase Auth. Les mots de passe et jetons de fournisseur ne sont jamais accessibles à Piloz.</span></aside>`;}catch(error){fail(error);baseRender.call(modern,'settings',s);}}
 async function linkIdentity(provider){try{const runtime=global.PilozRuntime,params=new URLSearchParams({provider,redirect_to:location.origin+location.pathname+'#settings/security'});if(provider==='azure')params.set('scopes','openid email profile');const response=await fetch(runtime.config.url.replace(/\/$/,'')+'/auth/v1/user/identities/authorize?'+params,{headers:{apikey:runtime.config.key,Authorization:'Bearer '+runtime.session.access_token}}),result=await response.json().catch(()=>({}));if(!response.ok||!result.url)throw new Error(result.msg||result.message||'Liaison indisponible.');location.assign(result.url);}catch(error){fail(error);}}
 async function unlinkIdentity(identityId){if(!global.confirm('Délier cette méthode de connexion ?'))return;try{const runtime=global.PilozRuntime,response=await fetch(runtime.config.url.replace(/\/$/,'')+'/auth/v1/user/identities/'+encodeURIComponent(identityId),{method:'DELETE',headers:{apikey:runtime.config.key,Authorization:'Bearer '+runtime.session.access_token}}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.msg||result.message||'La méthode n’a pas pu être déliée.');notify('Méthode de connexion déliée.','success');renderSecurity(state());}catch(error){fail(error);}}

 function renderRoute(route,s){const current=path();if(route==='settings'&&['settings','settings/overview'].includes(current)){renderSettingsDashboard(s);return true;}if(route==='settings'&&current==='settings/extensions'){renderExtensions(s);return true;}if(route==='settings'&&current==='settings/sales-terms'){renderSalesTerms(s);return true;}if(route==='settings'&&current==='settings/security'){renderSecurity(s);return true;}if(route==='accounting-payments'){renderPayments(s);return true;}if(route==='accounting-exports'){renderExports(s);return true;}if(route==='accounting-vat-cash'){renderVatCash(s);return true;}if(route==='accounting-settings'){renderAccountingSettings(s);return true;}return baseRender.call(modern,route,s);}
 modern.renderRoute=renderRoute;
